WITH department_totals AS (SELECT dept_id, COUNT(DISTINCT salary) AS unique_job_titles, MAX(salary) AS max_salary FROM employees WHERE salary >= 87000 GROUP BY dept_id) SELECT d.id, d.budget, d.location, dt.unique_job_titles, dt.max_salary FROM departments d INNER JOIN department_totals dt ON d.id = dt.dept_id WHERE dt.unique_job_titles > 7 ORDER BY dt.unique_job_titles, d.location, id LIMIT 1
